#!/usr/bin/env python3
"""Ross's transcript sync: find untranscribed Friend-Message commits, order them, append verbatim."""
import subprocess, sys, re
from pathlib import Path

REPO = "/home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill"
MAIN = Path("/tmp/ross-main")
FRIENDS = ["rachel", "monica", "phoebe", "joey", "chandler", "ross"]
BRANCHES = {f"friend/{n}" for n in FRIENDS}

def git(*a, repo=REPO):
    return subprocess.run(["git", "-C", repo, *a], capture_output=True, text=True, check=True).stdout

def filed_shas():
    out = set()
    for p in MAIN.glob("S*/E*.md"):
        for m in re.finditer(r"^Source: friend/[\w-]+ @ ([0-9a-f]{40})", p.read_text(encoding="utf-8"), re.M):
            out.add(m.group(1))
    return out

def enumerate_messages():
    msgs = []
    for b in FRIENDS:
        for sha in git("rev-list", f"origin/friend/{b}").split():
            body = git("log", "-1", "--format=%B", sha)
            if not re.search(r"^Friend-Message: 1\s*$", body, re.M):
                continue
            ep = re.search(r"^Episode: (\S+)", body, re.M)
            sp = re.search(r"^Speaker: (\w+)", body, re.M)
            rt = re.search(r"^Reply-To: (\S+)", body, re.M)
            msgs.append(dict(sha=git("rev-parse", sha).strip(), short=sha[:8], branch=f"friend/{b}",
                             ts=git("log", "-1", "--format=%cI", sha).strip(),
                             episode=ep.group(1) if ep else "S01/E01",
                             speaker=sp.group(1) if sp else "?",
                             reply_to=rt.group(1) if rt else "none", body=body))
    return msgs

def utterance(body):
    lines = body.split("\n")
    idx = max(i for i, l in enumerate(lines) if l.startswith("Reply-To:"))
    j = idx + 1
    while j < len(lines) and lines[j].strip() != "": j += 1
    while j < len(lines) and lines[j].strip() == "": j += 1
    return "\n".join(lines[j:]).rstrip("\n")

def main():
    apply = "--apply" in sys.argv
    have = filed_shas()
    msgs = enumerate_messages()
    missing = [m for m in msgs if m["sha"] not in have]
    missing.sort(key=lambda m: (m["ts"], m["sha"]))
    print(f"total messages: {len(msgs)}  filed: {len(have)}  missing: {len(missing)}")
    for m in missing:
        print(f"  {m['ts']} {m['speaker']:<8} {m['episode']} {m['branch']} @ {m['sha'][:10]}")
    if not apply or not missing:
        return
    by_ep = {}
    for m in missing:
        by_ep.setdefault(m["episode"], []).append(m)
    for ep, items in sorted(by_ep.items()):
        path = MAIN / f"{ep}.md"
        if not path.exists():
            print(f"!! {path} does not exist; skip (open episode first)")
            continue
        text = path.read_text(encoding="utf-8")
        if not text.endswith("\n\n"):
            text = text.rstrip("\n") + "\n\n"
        for m in items:
            text += f"**{m['speaker']}** ({m['ts']})\n\nSource: {m['branch']} @ {m['sha']}\n\n{utterance(m['body'])}\n\n"
            print(f"APPENDED {m['speaker']} {m['sha'][:10]} -> {path.name}")
        path.write_text(text, encoding="utf-8")

main()
PYEOF
