#!/usr/bin/env python3
"""Verify every transcript entry matches its source commit verbatim (paragraph-state parser)."""
import subprocess, re
from pathlib import Path

REPO = "/home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill"
MAIN = Path("/tmp/ross-main")

def git(*a):
    return subprocess.run(["git", "-C", REPO, *a], capture_output=True, text=True, check=True).stdout.strip()

def commit_data(sha):
    lines = git("log", "-1", "--format=%B", sha).split("\n")
    idx = max(i for i, l in enumerate(lines) if l.startswith("Reply-To:"))
    j = idx + 1
    while j < len(lines) and lines[j].strip() != "": j += 1
    while j < len(lines) and lines[j].strip() == "": j += 1
    utt = "\n".join(lines[j:]).rstrip("\n")
    ts = git("log", "-1", "--format=%cI", sha)
    refs = [r.strip().replace("origin/", "") for r in git("branch", "-r", "--contains", sha).split()]
    branch = [r for r in refs if r.startswith("friend/")]
    return dict(ts=ts, utt=utt, branch=branch[0] if branch else "?")

problems, seen, total = [], {}, 0
KNOWN = {"Rachel", "Monica", "Phoebe", "Joey", "Chandler", "Ross"}
for path in sorted(MAIN.glob("S*/E*.md")):
    text = path.read_text(encoding="utf-8")
    parts = re.split(r"^---\s*$", text, maxsplit=2, flags=re.MULTILINE)
    body = parts[2] if len(parts) == 3 else text
    cur = None
    for para in re.split(r"\n[ \t]*\n", body):
        if not para.strip():
            continue
        h = re.fullmatch(r"\*\*(\w+)\*\* \(([^)]+)\)", para.strip())
        if h:
            if cur: problems.append(f"UNFLUSHED turn in {path.name}")
            cur = dict(speaker=h.group(1), ts=h.group(2), sha=None, branch=None, paras=[])
            continue
        s = re.fullmatch(r"Source: (friend/[\w-]+) @ ([0-9a-f]{40})", para.strip())
        if s:
            if cur is None or cur["paras"] or cur["sha"]:
                problems.append(f"STRAY/MISPLACED Source in {path.name}: {s.group(2)[:10]}")
                cur = None
            else:
                cur["branch"], cur["sha"] = s.group(1), s.group(2)
            continue
        if cur is None:
            problems.append(f"ORPHAN paragraph in {path.name}: {para.strip()[:50]!r}")
            continue
        cur["paras"].append(para)
        if len(cur["paras"]) == 1:  # first dialogue paragraph closes the turn
            total += 1
            sha = cur["sha"]
            if sha is None:
                problems.append(f"NO SOURCE for {cur['speaker']} in {path.name}")
            elif sha in seen:
                problems.append(f"DUPLICATE {sha[:10]} in {path.name} and {seen[sha]}")
            else:
                seen[sha] = path.name
                cd = commit_data(sha)
                utt = "\n\n".join(cur["paras"])
                if cd["utt"] != utt:
                    problems.append(f"TEXT MISMATCH {path.name} {sha[:10]} ({cur['speaker']})\n    file: {utt[:110]!r}\n    comm: {cd['utt'][:110]!r}")
                if cd["ts"] != cur["ts"]: problems.append(f"TS MISMATCH {path.name} {sha[:10]} {cur['ts']} vs {cd['ts']}")
                if cd["branch"] != cur["branch"]: problems.append(f"BRANCH MISMATCH {path.name} {sha[:10]} {cur['branch']} vs {cd['branch']}")
                if not utt.startswith(cur["speaker"] + ":"): problems.append(f"SPEAKER PREFIX {path.name} {sha[:10]} {utt[:40]!r}")
                if cur["speaker"] not in KNOWN: problems.append(f"UNKNOWN SPEAKER {path.name} {cur['speaker']}")
                cur = None

print(f"entries checked: {total}  unique shas: {len(seen)}")
if problems:
    print(f"PROBLEMS: {len(problems)}")
    for p in problems[:30]: print(" -", p)
else:
    print("ALL ENTRIES VERBATIM, UNIQUE, AND CONSISTENT")
